from selenium.common.exceptions import TimeoutException, NoSuchElementException
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_core.exceptions import OutOfRange


class PagePart(object):
    def __init__(self, driver):
        self._driver = driver

    def _until(self, method, timeout):
        return WebDriverWait(self._driver, timeout).until(method)

    def _until_not(self, method, timeout):
        WebDriverWait(self._driver, timeout).until_not(method)

    def _wait_for_element_by(self, locator, timeout=60):
        self._until(EC.presence_of_element_located(locator), timeout)

    def _is_element_enabled(self, locator, timeout):
        """
        Checks whether web element becomes enabled before timeout.
        :param locator: web element locator i.e. (By.ID, "someID")
        :type locator: tuple(selenium.webdriver.common.by.By, str)
        :param timeout: time to wait for web element to be enabled, in seconds
        :type timeout: int
        :return: True, if web element becomes enabled before timeout, False otherwise
        :rtype: bool
        """
        try:
            self.wait_for_enable(locator, timeout)
            return True
        except TimeoutException:
            return False

    def _is_text_present_in_element(self, locator, text, timeout):
        """
        Checks whether text becomes present in web element before timeout.
        :param locator: web element locator i.e. (By.ID, "someID")
        :type locator: tuple(selenium.webdriver.common.by.By, str)
        :param text: text expected to be present in web element
        :type text: str
        :param timeout: time to wait for text to be present in web element, in seconds
        :type timeout: int
        :return: True, if text becomes present in web element before timeout, False otherwise
        :rtype: bool
        """
        try:
            self._until(EC.text_to_be_present_in_element(locator, text), timeout)
            return True
        except TimeoutException:
            return False

    def wait_for_visibility(self, locator, timeout=60):
        """
        Wait for timeout seconds until element will become visible

        :param locator: a tuple with locator for element for instance (By.ID, "someID") see selenium doc for more
        :param timeout: time until method exits with error
        """
        self._until(EC.visibility_of_element_located(locator), timeout)

    def wait_for_enable(self, locator, timeout=60):
        """
        Wait for timeout seconds until element will become enable
        check element if is enabled until timeout
        :param locator: a tuple with locator for element for instance (By.ID, "someID") see selenium doc for more
        :param timeout: time until method exits with error
        """
        return self._until(EC.element_to_be_clickable(locator), timeout)

    def insert_text_to_field(self, id, text):
        """
        Enters given text to field with given id.

        :param id: ID of input element
        :param text: Text to insert into text field
        """
        elem = self._driver.find_element_by_id(id)
        elem.clear()
        elem.send_keys(text)

    def insert_text_to_enabled_field(self, locator, text, timeout):
        """
        Enters text into text field only if text field is enabled before timeout.
        :param locator: text field locator i.e. (By.ID, "someID")
        :type locator: tuple(selenium.webdriver.common.by.By, str)
        :param text: text which will be entered into text field
        :type text: str
        :param timeout: time to wait for text field to be enabled, in seconds
        :type timeout: int
        :except selenium.common.exceptions.TimeoutException: raised if text field is disabled after timeout
        """
        self.wait_for_enable(locator, timeout)
        self.insert_text_to_field(locator[1], text)

    def input_text_to_field_by_element(self, element, value):
        """
        Enters text into text field by webelement.
        :param element: webelement
        :param value: (str, int) text, number
        :return:
        """
        element.clear()
        element.send_keys(value)

    def click_button(self, id):
        """
        Clicks button with given id

        :param id: button's id
        """
        self._driver.find_element_by_id(id).click()

    def click_element_by_xpath(self, xpath, index=0):
        """
        Clicks element with given xpath

        :param xpath: element's xpath
        :param index: (int) index of element in returned list
        """
        self._driver.find_elements_by_xpath(xpath)[index].click()

    def select_checkbox_by_xpath(self, xpath):
        """
        select checkbox with given xpath

        :param xpath: element's xpath
        """
        checkbox = self._driver.find_element_by_xpath(xpath)
        if not checkbox.is_selected():
            checkbox.click()

    def unselect_checkbox_by_xpath(self, xpath):
        """
        unselect checkbox with given xpath

        :param xpath: element's xpath
        """
        checkbox = self._driver.find_element_by_xpath(xpath)
        if checkbox.is_selected():
            checkbox.click()

    def click_enabled_element(self, locator, timeout):
        """
        Clicks web element only if it is enabled before timeout.
        :param locator: web element locator i.e. (By.ID, "someID")
        :type locator: tuple(selenium.webdriver.common.by.By, str)
        :param timeout: time to wait for web element to be enabled, in seconds
        :type timeout: int
        :except selenium.common.exceptions.TimeoutException: raised if web element is disabled after timeout
        """
        self.wait_for_enable(locator, timeout)
        self.click_button(locator[1])

    def click_enabled_element_firefox_bug_workaround(self, locator, timeout=30, td_num=None):
        """
        Clicks web element only if it is enabled before timeout.
        With tr having multiple tds one need to actually click specific td

        :param locator: web element locator i.e. (By.ID, "someID")
        :type locator: tuple(selenium.webdriver.common.by.By, str)
        :param timeout: time to wait for web element to be enabled, in seconds
        :type timeout: int
        :param td_num: number of cell in tr element,
         needs to be provided if there are more than one for Firefox workaround
        :type td_num:
        :except selenium.common.exceptions.TimeoutException: raised if web element is disabled after timeout

        """
        if td_num is None:
            self.click_enabled_element(locator, timeout)
        else:
            self.wait_for_enable(locator, timeout)
            elem = self._driver.find_element_by_id(locator[1])
            elem.find_element_by_xpath("./td[{}]".format(td_num)).click()

    def check_if_exists(self, locator, timeout=5):
        """
        Checks whether given web element exists.
        :param locator: web element locator i.e. (By.ID, "someID")
        :type locator: tuple(selenium.webdriver.common.by.By, str)
        :param timeout: time to wait for element to become available, in seconds
        :type timeout: int
        :return: True if web element exists, False otherwise
        :rtype: bool
        """
        try:
            self._wait_for_element_by(locator, timeout)
            return True
        except TimeoutException:
            return False

    def check_if_visible(self, locator, timeout=5):
        """
        Checks whether given web element is visible.
        :param locator: web element locator i.e. (By.ID, "someID")
        :type locator: tuple(selenium.webdriver.common.by.By, str)
        :param timeout: time to wait for element to become visible, in seconds
        :type timeout: int
        :return: True if web element is visible, False otherwise
        :rtype: bool
        """
        try:
            self.wait_for_visibility(locator, timeout)
            element = self._driver.find_element(*locator)
            return element.is_displayed()
        except TimeoutException:
            return False

    def is_id_present(self, id, timeout=30):
        try:
            self._wait_for_element_by((By.ID, id), timeout=timeout)
            self._driver.find_element_by_id(id)
            return True
        except NoSuchElementException as _:
            return False

    def check_if_element_has_text(self, locator, text, timeout=5):
        """
        Checks whether given web element contains given text.
        :param locator: web element locator i.e. (By.ID, "someID")
        :type locator: tuple(selenium.webdriver.common.by.By, str)
        :param text: text that will be expected in web element
        :type text: str
        :param timeout: time to wait (in seconds) for given text to be present in web element; defaults to 5 seconds
        :type timeout: int
        :return: True if web element contains given text, False otherwise
        :rtype: bool
        """
        try:
            self._until(EC.text_to_be_present_in_element(locator, text), timeout)
            return True
        except TimeoutException:
            return False

    def input_number_to_text_field(self, new_value, timeout, xpath, min_value, max_value):
        """
        Change value to new one at text filed
        :param new_value: (int) new number input
        :param timeout: (int) time to wait for element to become visible, in seconds
        :param xpath: element's xpath
        :param min_value: lowest acceptable value of the number
        :param max_value: biggest acceptable value of the number
        :raises OutOfRange: when new_value is out of range <min_value, max_value>
        """
        if new_value not in range(min_value, max_value + 1):
            raise OutOfRange('Your value: {} is out of range: {}-{}'.format(new_value, min_value, max_value))

        self._wait_for_element_by((By.XPATH, xpath), timeout)
        self.wait_for_visibility((By.XPATH, xpath), timeout)
        elem = self._driver.find_element_by_xpath(xpath)
        self.input_text_to_field_by_element(elem, new_value)

    def open_dropdown_list(self, xpath):
        """
        Open selected dropdown list by xpath

        :param xpath: element's xpath
        """
        self._wait_for_element_by((By.XPATH, xpath))
        self.wait_for_visibility((By.XPATH, xpath))
        self._driver.find_element_by_xpath(xpath).click()

    def get_gnb_operation_state_status(self, timeout=10):
        """
        Get gNB operation state status
        :param timeout: int, time to wait for status to be available
        :return: string with current gNB operation state status
        """
        timeout = int(timeout)
        icon_xpath = '//*[@id="gnb-operation-state-icon"]'
        text_xpath = '//*[@id="gnb-operation-state-text"]'
        self._wait_for_element_by((By.XPATH, icon_xpath), timeout)
        status = self._driver.find_element_by_xpath(text_xpath).text
        return str(status)


class BasicPage(PagePart):
    account_banner_id = "TA_banner_account"
    account_management_link_id = "account-management-link"
    change_local_user_password_link_id = "change-local-user-password-link"

    def __init__(self, driver):
        super(BasicPage, self).__init__(driver)

    def logout(self):
        self._wait_for_element_by((By.ID, 'logout-link'))
        self.click_button('logout-link')

    def check_if_logout_is_possible(self, timeout=10):
        """
        Checks whether web element Logout button is visible
        :param timeout: time to wait for element to become visible, in seconds
        :type timeout: int
        :return: True if web Logout element is visible, False otherwise
        :rtype: bool
        """
        try:
            self.check_if_visible((By.ID, "logout-link"), timeout=timeout)
            return True
        except TimeoutException:
            return False

    def change_password(self, username, old_password, new_password):
        """
        Opens Account Management and changes password for given username.
        :param username: username for which password will be changed
        :type username: str
        :param old_password: current password for given username
        :type old_password: str
        :param new_password: password which will be set for given username
        :type new_password: str
        :return: True, if password was changed successfully, False otherwise
        :rtype: bool
        :except selenium.common.exceptions.TimeoutException: raised if any of the required web elements is unavailable
        """
        account_management = self._open_account_management()
        return account_management.change_password(username, old_password, new_password)

    def change_password_for_local_user(self, username, new_password):
        """
        Opens Local User Account Management and changes password for given username.
        :param username: username for which password will be changed
        :type username: str
        :param new_password: password which will be set for given username
        :type new_password: str
        :return: True, if password was changed successfully, False otherwise
        :rtype: bool
        :except selenium.common.exceptions.TimeoutException: raised if any of the required web elements is unavailable
        """
        self._until(EC.text_to_be_present_in_element((By.ID, "user-name"), username), 10)
        local_user_account_management = self._open_local_user_account_management()
        return local_user_account_management.change_password(username, new_password)

    def check_if_password_can_be_changed(self, username=None, old_password=None,
                                         new_password=None, confirm_password=None):
        """
        Opens Account Management, enters all provided account data and checks, whether Change button is enabled.
        If some data will be missing (None or empty string) nothing will be entered into corresponding text field.
        :param username: text which will be entered into Username text field
        :type username: str
        :param old_password: text which will be entered into Old password text field
        :type old_password: str
        :param new_password: text which will be entered into New password text field
        :type new_password: str
        :param confirm_password: text which will be entered into Confirm password text field
        :type confirm_password: str
        :return: True, if Change button is enabled (password can be changed), False otherwise
        :rtype: bool
        :except selenium.common.exceptions.TimeoutException: raised if any of the required web elements is unavailable
        """
        account_management = self._open_account_management()
        return account_management.check_if_password_can_be_changed(username, old_password, new_password,
                                                                   confirm_password)

    def _open_account_management(self):
        """
        Opens Account Management popup.
        :return: Account Management popup object
        :rtype: AccountManagementPopup
        """
        self.click_enabled_element((By.ID, self.account_banner_id), 30)
        self.click_enabled_element((By.ID, self.account_management_link_id), 5)
        return AccountManagementPopup(self._driver)

    def _open_local_user_account_management(self):
        """
        Opens Local User Account Management popup.
        :return: Local User Account Management Popup popup object
        :rtype: LocalUserAccountManagementPopup
        """
        self.click_enabled_element((By.ID, self.account_banner_id), 30)
        self.click_enabled_element((By.ID, self.change_local_user_password_link_id), 5)
        return LocalUserAccountManagementPopup(self._driver)


class Modal(BasicPage):
    def __init__(self, driver):
        super(Modal, self).__init__(driver)

    def wait_for_invisibility(self, locator, timeout=10):
        """
        Wait for timeout seconds until element will become invisible

        :param locator: a tuple with locator for element for instance (By.ID, "someID") see selenium doc for more
        :param timeout: time until method exits with error
        """
        self._until(EC.invisibility_of_element_located(locator), timeout)


class AccountManagementPopup(PagePart):
    username_input_id = "acc-man-service-username-input"
    password_input_id = "acc-man-service-password-input"
    new_password_input_id = "acc-man-service-new-password-input"
    confirm_password_input_id = "acc-man-service-confirm-password-input"
    change_button_id = "acc-man-service-change-button"
    password_change_status_label_id = "ariaID04"
    close_button_id = "account-management-close-button"

    def change_password(self, username, old_password, new_password):
        """
        Changes password for given username.
        :param username: username for which password will be changed
        :type username: str
        :param old_password: current password for given username
        :type old_password: str
        :param new_password: password which will be set for given username
        :type new_password: str
        :return: True, if password was changed successfully, False otherwise
        :rtype: bool
        :except selenium.common.exceptions.TimeoutException: raised if any of the required web elements is unavailable
        """
        self._enter_account_data(username, old_password, new_password, new_password)
        password_changed = False
        if self._is_change_button_enabled(5):
            self._confirm_password_change()
            password_changed = self._wait_for_successful_password_change()
        self._close_account_management()
        return password_changed

    def check_if_password_can_be_changed(self, username=None, old_password=None,
                                         new_password=None, confirm_password=None):
        """
        Enters all provided account data and checks, whether Change button is enabled.
        If some data will be missing (None or empty string) nothing will be entered into corresponding text field.
        :param username: text which will be entered into Username text field
        :type username: str
        :param old_password: text which will be entered into Old password text field
        :type old_password: str
        :param new_password: text which will be entered into New password text field
        :type new_password: str
        :param confirm_password: text which will be entered into Confirm password text field
        :type confirm_password: str
        :return: True, if Change button is enabled (password can be changed), False otherwise
        :rtype: bool
        :except selenium.common.exceptions.TimeoutException: raised if any of the required web elements is unavailable
        """
        self._enter_account_data(username, old_password, new_password, confirm_password)
        password_can_be_changed = self._is_change_button_enabled(5)
        self._close_account_management()
        return password_can_be_changed

    def _enter_account_data(self, username, old_password, new_password, confirm_password):
        """
        Enters account data into appropriate text fields.
        If some data will be missing (None or empty string) nothing will be entered into corresponding text field.
        :param username: text which will be entered into Username text field;
        :type username: str
        :param old_password: text which will be entered into Old password text field;
        :type old_password: str
        :param new_password: text which will be entered into New password text field
        :type new_password: str
        :param confirm_password: text which will be entered into Confirm password text field
        :type confirm_password: str
        :except selenium.common.exceptions.TimeoutException: raised if any text field is disabled after timeout
        """
        if username:
            self.insert_text_to_enabled_field((By.ID, self.username_input_id), username, 10)

        if old_password:
            self.insert_text_to_enabled_field((By.ID, self.password_input_id), old_password, 10)

        if new_password:
            self.insert_text_to_enabled_field((By.ID, self.new_password_input_id), new_password, 10)

        if confirm_password:
            self.insert_text_to_enabled_field((By.ID, self.confirm_password_input_id), confirm_password, 10)

    def _confirm_password_change(self):
        """Starts password change procedure by clicking Change button."""
        self.click_button((self.change_button_id))

    def _wait_for_successful_password_change(self):
        """Checks whether password changing procedure finished successfully by checking text in status label."""
        return self._is_text_present_in_element((By.ID, self.password_change_status_label_id),
                                                "Service account password successfully changed", 30)

    def _is_change_button_enabled(self, timeout):
        """
        Checks whether Change button becomes enabled before timeout.
        :param timeout: time to wait for Change button to be enabled, in seconds
        :type timeout: int
        :return: True, if Change button becomes enabled before timeout, False otherwise
        :rtype: bool
        """
        return self._is_element_enabled((By.ID, self.change_button_id), timeout)

    def _close_account_management(self):
        """Closes Account Management popup."""
        self.click_enabled_element((By.ID, self.close_button_id), 5)


class LocalUserAccountManagementPopup(PagePart):
    username_input_id = "change-password-username-input"
    new_password_input_id = "change-password-password-input"
    confirm_new_password_input_id = "change-password-confirm-password-input"
    change_button_id = "change-password-change-button"
    close_button_id = "change-password-close"
    password_change_status_label_id = "change-password-status-message"

    def change_password(self, username, new_password):
        """
        Changes password for given username.
        :param username: username for which password will be changed
        :type username: str
        :param new_password: password which will be set for given username
        :type new_password: str
        :return: True, if password was changed successfully, False otherwise
        :rtype: bool
        :except selenium.common.exceptions.TimeoutException: raised if any of the required web elements is unavailable
        """
        self._enter_account_data(username, new_password, new_password)
        password_changed = False
        if self._is_change_button_enabled(5):
            self._confirm_password_change()
            password_changed = self._wait_for_successful_password_change()
        self._close_account_management()
        return password_changed

    def _enter_account_data(self, username, new_password, confirm_password):
        """
        Enters account data into appropriate text fields.
        If some data will be missing (None or empty string) nothing will be entered into corresponding text field.
        :param username: text which will be entered into Username text field;
        :type username: str
        :param new_password: text which will be entered into New password text field
        :type new_password: str
        :param confirm_password: text which will be entered into Confirm password text field
        :type confirm_password: str
        :except selenium.common.exceptions.TimeoutException: raised if any text field is disabled after timeout
        """
        if username:
            self.insert_text_to_enabled_field((By.ID, self.username_input_id), username, 10)

        if new_password:
            self.insert_text_to_enabled_field((By.ID, self.new_password_input_id), new_password, 10)

        if confirm_password:
            self.insert_text_to_enabled_field((By.ID, self.confirm_new_password_input_id), confirm_password, 10)

    def _confirm_password_change(self):
        """Starts password change procedure by clicking Change button."""
        self.click_button(self.change_button_id)

    def _wait_for_successful_password_change(self):
        """Checks whether password changing procedure finished successfully by checking text in status label."""
        return self._is_text_present_in_element((By.ID, self.password_change_status_label_id),
                                                "Account successfully updated.", 30)

    def _is_change_button_enabled(self, timeout):
        """
        Checks whether Change button becomes enabled before timeout.
        :param timeout: time to wait for Change button to be enabled, in seconds
        :type timeout: int
        :return: True, if Change button becomes enabled before timeout, False otherwise
        :rtype: bool
        """
        return self._is_element_enabled((By.ID, self.change_button_id), timeout)

    def _close_account_management(self):
        """Closes Account Management popup."""
        self.click_enabled_element((By.ID, self.close_button_id), 5)
